/// What a conflict of the overview is.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ConflictKind {
    /// Two jobs of heavy work on one volume overlap.
    Volume,
    /// A disk test overlaps heavy work on a volume of that disk.
    Disk,
    /// A job that follows the maintenance window starts outside it.
    Maintenance,
}

/// What happens because of a conflict.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ConflictOutcome {
    /// The second job waits in the queue for the first.
    Waits,
    /// The first job (a scrub) gives way to the second and resumes after it.
    GivesWay,
    /// Both run (a disk test slows itself down beside more urgent work).
    BothRun,
    /// The job waits for the maintenance window.
    Deferred,
    /// The job is skipped: the maintenance window opens after its deadline.
    Skipped,
}

/// A conflict found in the overview, with a plain sentence (English; the interface builds
/// its own from the other fields).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct OverviewConflict {
    pub kind: ConflictKind,
    pub outcome: ConflictOutcome,
    /// The job that started (or starts) first; for `maintenance`, the job outside the window.
    pub first: String,
    pub first_ms: u64,
    /// The other job (absent for `maintenance`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub second: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub second_ms: Option<u64>,
    /// The job that waits, gives way or is deferred.
    pub affected: String,
    /// What both claim (the volume or the disk).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub resource: Option<Resource>,
    /// When the maintenance window opens (`deferred`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub opens_ms: Option<u64>,
    /// "Scrub of data (≈9 h) overlaps the backup offsite at 02:00; the backup will wait".
    pub sentence: String,
}

/// `GET /api/v1/scheduler/runs?task&outcome&from&limit`: the history of every task, newest
/// first (without output).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct RunsPage {
    pub runs: Vec<TaskRun>,
    /// The names of the tasks in `runs` (id → name; English for rynas's own jobs).
    #[serde(default)]
    pub names: std::collections::BTreeMap<String, String>,
    /// More older runs match (ask again with `before` = the last id).
    #[serde(default)]
    pub more: bool,
}

/// The `outcome` filter of `GET /api/v1/scheduler/runs`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum RunOutcome {
    Ok,
    Failed,
    Skipped,
    /// Gave way to more urgent work (a scrub), resumes by itself.
    Yielded,
}

fn is_zero(n: &u8) -> bool {
    *n == 0
}

/// Live output of the running invocation (`GET /api/v1/scheduler/tasks/{id}/live`, SSE):
/// first event `run`, data [`LiveRun`].
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct LiveRun {
    /// systemd invocation id of the run being followed.
    pub invocation_id: String,
    #[serde(default)]
    pub start_ms: Option<u64>,
}

/// Last event of a live output stream (`end`).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct LiveEnd {
    /// `false`: nothing was running when the stream opened.
    pub ran: bool,
}

/// Event names of the live output stream. `lines` carries a JSON array of strings: one
/// journal entry each (one output line without its newline, carriage returns kept, bytes
/// that are not UTF-8 replaced by U+FFFD).
pub mod live_event {
    pub const RUN: &str = "run";
    pub const LINES: &str = "lines";
    pub const END: &str = "end";
    /// The journal could not be read (data `{"message": …}`); the stream ends after it.
    /// (Not `error`: that name is the browser's own connection error event.)
    pub const FAILED: &str = "failed";
}

/// `POST /api/v1/scheduler/tasks/preview-calendar`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct CalendarPreviewRequest {
    pub expression: String,
    #[serde(default)]
    pub syntax: CalendarSyntax,
    /// Number of next runs to compute (default 5, at most 20).
    #[serde(default)]
    pub count: Option<u32>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "snake_case")]
pub enum CalendarSyntax {
    /// systemd `OnCalendar=`.
    #[default]
    Calendar,
    /// Five-field crontab line (`m h dom mon dow`) or `@daily`-style shortcut.
    Cron,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct CalendarPreview {
    pub valid: bool,
    /// The `OnCalendar=` expression to store (converted from cron if needed).
    #[serde(default)]
    pub on_calendar: String,
    /// systemd's normalized form.
    #[serde(default)]
    pub normalized: String,
    /// Next runs.
    #[serde(default)]
    pub next_ms: Vec<u64>,
    #[serde(default)]
    pub error: Option<String>,
}

/// `POST /api/v1/scheduler/preview`: a schedule as the NAS will run it. Give `expression`
/// (an `OnCalendar=` expression, or a crontab line with `syntax: cron`) or `trigger`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct SchedulePreviewRequest {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub expression: Option<String>,
    #[serde(default)]
    pub syntax: CalendarSyntax,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub trigger: Option<TaskTrigger>,
    /// IANA time zone; default the NAS's.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub tz: Option<String>,
    /// Number of next runs (default 5, at most 20).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub count: Option<u32>,
    /// An interval trigger's allowed start window (a PC's backup plan, S6): its starts come
    /// only inside it (168 cells, Sunday first, local time).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub window: Option<String>,
    /// An interval trigger's last good run (its end): the next start is due an interval
    /// later; absent: due now.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub last_ms: Option<u64>,
    /// A PC's interval counts from here instead of `last_ms`: its last good run's start
    /// (agents from 0.8.24; `PcDevice::interval_from_ms`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub interval_from_ms: Option<u64>,
}

/// Answer of `POST /api/v1/scheduler/preview` (always 200; `valid: false` with `error`).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct SchedulePreview {
    pub valid: bool,
    /// The time zone of the runs (IANA name; empty when the NAS's zone has none).
    #[serde(default)]
    pub tz: String,
    /// The `OnCalendar=` expression to store (from cron or a preset), for calendar triggers.
    #[serde(default)]
    pub on_calendar: String,
    /// systemd's normalized form of it.
    #[serde(default)]
    pub normalized: String,
    /// The preset the expression is, if any: the structured description the interface puts
    /// into words; `None` with `normalized` set: an advanced expression.
    #[serde(default)]
    pub preset: Option<Recurrence>,
    /// Next runs.
    #[serde(default)]
    pub runs: Vec<PreviewRun>,
    /// A valid schedule that systemd will never start again: a date in the past, or an
    /// expression systemd gives up on around a DST change at midnight (the timer would stay
    /// without a next run).
    #[serde(default)]
    pub no_next_run: bool,
    /// The expression has no end but systemd stops scheduling it within the next year (at a
    /// DST change at midnight): after its last run the timer has no next run.
    #[serde(default)]
    pub stops: bool,
    /// When `stops`: the local date (`YYYY-MM-DD`) of the change where it stops.
    #[serde(default)]
    pub stops_on: Option<String>,
    /// Clock changes in the next year that change when the schedule runs.
    #[serde(default)]
    pub dst: Vec<DstNote>,
    #[serde(default)]
    pub error: Option<String>,
}

/// One next run.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct PreviewRun {
    pub ms: u64,
    /// Wall-clock time in the preview's zone, `YYYY-MM-DD HH:MM:SS`.
    pub local: String,
    /// Zone abbreviation at that moment (`CET`, `CEST`), empty when the zone has none.
    #[serde(default)]
    pub abbreviation: String,
    /// Seconds east of UTC at that moment.
    pub offset_s: i32,
}

/// A clock change that affects a schedule: on `date` the clocks jump from `from` to `to`
/// (local times, `HH:MM`). Forward: the schedule's times in between do not exist that day and
/// are skipped. Back: its times in between exist twice and run once (the first time).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct DstNote {
    /// The moment of the change.
    pub ms: u64,
    /// `YYYY-MM-DD`, local.
    pub date: String,
    pub forward: bool,
    pub from: String,
    pub to: String,
}

/// `GET /api/v1/scheduler/system-timers`: systemd timers not generated by rynas (read-only).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct SystemTimer {
    pub unit: String,
    pub activates: String,
    #[serde(default)]
    pub next_ms: Option<u64>,
    #[serde(default)]
    pub last_ms: Option<u64>,
    /// `OnCalendar=` expressions of the timer, if any.
    #[serde(default)]
    pub on_calendar: Vec<String>,
}

/// `GET /api/v1/scheduler/cron-entries`: crontab lines found on the system (read-only).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
pub struct CronEntry {
    /// `/etc/crontab`, `/etc/cron.d/<name>` or `/var/spool/cron/crontabs/<user>`.
    pub source: String,
    pub line: u32,
    /// The five time fields or the `@` shortcut.
    pub schedule: String,
    pub user: String,
    pub command: String,
    /// The equivalent trigger, when there is one (`@reboot` is a boot trigger).
    #[serde(default)]
    pub trigger: Option<TaskTrigger>,
}

/// The tasks of rynas's own recurring jobs, owned by their feature and built from its
/// settings (S3 of `docs/research/scheduling.md`: the loops rynasd ran itself). Their
/// schedules are the ones the loops had: the same times, windows and intervals.
pub mod system {
    use super::{
        MissedPolicy, NotifyPolicy, RunPolicy, ScheduledTask, TaskAction, TaskOwner, TaskTrigger,
    };
    use crate::docker::AutoUpdateSettings;
    use crate::updates::AutoUpdates;

    pub const UPDATES_CHECK: &str = "updates-check";
    pub const SYSTEM_UPGRADE: &str = "apt-upgrade";
    pub const DOCKER_IMAGE_CHECK: &str = "docker-update-check";
    pub const DOCKER_AUTO_UPDATE: &str = "docker-auto-update";
    pub const APPS_CATALOG: &str = "apps-catalog-refresh";
    pub const PC_MAINTENANCE: &str = "pc-maintenance";
    pub const PC_RETENTION: &str = "pcbackup-retention";
    pub const MD_CHECK_START: &str = "mdcheck-start";
    pub const MD_CHECK_CONTINUE: &str = "mdcheck-continue";

    /// The ids of rynas's own jobs: a task made on the Task Scheduler page cannot take them.
    pub const RESERVED: &[&str] = &[
        UPDATES_CHECK,
        SYSTEM_UPGRADE,
        DOCKER_IMAGE_CHECK,
        DOCKER_AUTO_UPDATE,
        APPS_CATALOG,
        PC_MAINTENANCE,
        PC_RETENTION,
        MD_CHECK_START,
        MD_CHECK_CONTINUE,
    ];

    /// The system's own timers rynas gates (S4): task id, its service, its timer. A drop-in
    /// shipped with rynas adds the gate to the service (`ExecCondition=` and
    /// `ExecStopPost=`); a unit the system does not have is left out.
    pub const GATED_UNITS: &[(&str, &str, &str)] = &[
        (SYSTEM_UPGRADE, "apt-daily-upgrade.service", "apt-daily-upgrade.timer"),
        (MD_CHECK_START, "mdcheck_start.service", "mdcheck_start.timer"),
        (MD_CHECK_CONTINUE, "mdcheck_continue.service", "mdcheck_continue.timer"),
    ];

    /// The service and timer of a gated system task.
    pub fn gated_unit(id: &str) -> Option<(&'static str, &'static str)> {
        GATED_UNITS.iter().find(|(i, ..)| *i == id).map(|(_, s, t)| (*s, *t))
    }

    /// The md RAID check of mdadm's timers (`resume`: `mdcheck_continue`), as Debian ships
    /// them (the first Sunday of the month at 01:00, continued every night at 01:05 until
    /// every array is checked). Listed read-only; the schedule is the system's.
    pub fn md_check(resume: bool) -> ScheduledTask {
        let (id, name, desc, cal) = if resume {
            (
                MD_CHECK_CONTINUE,
                "RAID check (continued)",
                "Continues an md RAID check that reached its time limit. Run by the system's mdcheck_continue.timer.",
                "*-*-* 01:05:00",
            )
        } else {
            (
                MD_CHECK_START,
                "RAID check",
                "Checks the md RAID arrays for errors, a few hours each night. Run by the system's mdcheck_start.timer.",
                "Sun *-*-1..7 01:00:00",
            )
        };
        let mut t = task(
            id,
            name,
            desc,
            TaskAction::MdCheck { resume },
            TaskTrigger::Calendar { on_calendar: cal.into(), cron: None, persistent: false, randomized_delay_s: 0 },
        );
        t.policy.missed = Some(MissedPolicy::Skip);
        t.policy.jitter_s = Some(0);
        t
    }

    /// A late nightly PC maintenance runs up to this many hours after its hour.
    pub const PC_MAINTENANCE_CATCH_UP_H: u32 = 6;

    fn task(id: &str, name: &str, description: &str, action: TaskAction, trigger: TaskTrigger) -> ScheduledTask {
        let owner = TaskOwner::of_action(&action);
        ScheduledTask {
            id: id.into(),
            name: name.into(),
            description: description.into(),
            enabled: true,
            action,
            trigger,
            timeout_s: None,
            nice: None,
            io_weight: None,
            // these jobs notify by themselves, as before; a failed check only logged
            notify: NotifyPolicy::Never,
            notify_output: false,
            owner,
            policy: RunPolicy::default(),
        }
    }

    fn daily(hour: u8, minute: u8) -> String {
        format!("*-*-* {:02}:{:02}:00", hour.min(23), minute.min(59))
    }

    /// The "updates available" check: ten minutes after boot, then every 24 hours.
    pub fn updates_check() -> ScheduledTask {
        task(
            UPDATES_CHECK,
            "Updates check",
            "Refreshes the package lists when they are old and notifies about available updates. Set in Updates.",
            TaskAction::UpdatesCheck,
            TaskTrigger::Interval { hours: 24, after_boot_min: 10 },
        )
    }

    /// The automatic system updates: the daily window of `updates.auto` (its start, and a
    /// random delay over its whole length), caught up after boot as Debian's timer does.
    /// The `apt-daily-upgrade.timer` drop-in is rendered from this task.
    pub fn system_upgrade(a: &AutoUpdates) -> ScheduledTask {
        let jitter = u32::from(a.window_min) * 60;
        let mut t = task(
            SYSTEM_UPGRADE,
            "Automatic system updates",
            "Installs the updates of the operating system inside the update window. Set in Updates.",
            TaskAction::SystemUpgrade,
            TaskTrigger::Calendar {
                on_calendar: daily(a.hour, a.minute),
                cron: None,
                persistent: true,
                randomized_delay_s: jitter,
            },
        );
        t.enabled = a.mode != crate::updates::AutoMode::Off;
        t.policy.missed = Some(MissedPolicy::RunOnce { within_h: None });
        t.policy.jitter_s = Some(jitter);
        t.policy.window_min = Some(u32::from(a.window_min));
        t
    }

    /// The Docker image check: 5 minutes after boot at the earliest, then every 24 hours plus
    /// up to an hour at random.
    pub fn docker_image_check() -> ScheduledTask {
        let mut t = task(
            DOCKER_IMAGE_CHECK,
            "Docker image check",
            "Checks the images of the stacks for updates. Set in Docker.",
            TaskAction::DockerImageCheck,
            TaskTrigger::Interval { hours: 24, after_boot_min: 5 },
        );
        t.policy.jitter_s = Some(3600);
        t
    }

    /// The random delay of the automatic Docker updates inside their window: up to a third
    /// of it, at most 20 minutes.
    pub fn docker_window_delay_s(window_min: u16) -> u32 {
        (u32::from(window_min) / 3).clamp(1, 20) * 60
    }

    /// The automatic Docker updates: the daily window of `docker.auto_update`, on while some
    /// stack takes them. A start after boot inside the window still runs; outside it, not.
    pub fn docker_auto_update(a: &AutoUpdateSettings) -> ScheduledTask {
        let jitter = docker_window_delay_s(a.window_min);
        let mut t = task(
            DOCKER_AUTO_UPDATE,
            "Docker automatic updates",
            "Updates the stacks and apps that take automatic updates, one at a time, inside the update window. Set in Docker.",
            TaskAction::DockerAutoUpdate,
            TaskTrigger::Calendar {
                on_calendar: daily(a.hour, a.minute),
                cron: None,
                persistent: true,
                randomized_delay_s: jitter,
            },
        );
        t.enabled = a.stacks.values().any(|s| s.enabled);
        t.policy.missed = Some(MissedPolicy::RunOnce { within_h: None });
        t.policy.jitter_s = Some(jitter);
        t.policy.window_min = Some(u32::from(a.window_min));
        t
    }

    /// The online app catalog: a few minutes after boot at the earliest, then every 24 hours
    /// plus up to three hours at random; on while the online catalog is used.
    pub fn apps_catalog(on: bool) -> ScheduledTask {
        let mut t = task(
            APPS_CATALOG,
            "App catalog refresh",
            "Downloads the signed online app catalog when a newer one is published. Set in Apps.",
            TaskAction::AppsCatalog,
            TaskTrigger::Interval { hours: 24, after_boot_min: 2 },
        );
        t.enabled = on;
        t.policy.jitter_s = Some(3 * 3600);
        t
    }

    /// The nightly maintenance of the PC backup repositories at `hour`:00, caught up after
    /// boot up to [`PC_MAINTENANCE_CATCH_UP_H`] hours late.
    pub fn pc_maintenance(hour: u8) -> ScheduledTask {
        let mut t = task(
            PC_MAINTENANCE,
            "PC backup maintenance",
            "Retention, cleanup and check of the PC backup repositories, every night. Set in Backups › PCs.",
            TaskAction::PcMaintenance,
            TaskTrigger::Calendar {
                on_calendar: daily(hour, 0),
                cron: None,
                persistent: true,
                randomized_delay_s: 0,
            },
        );
        t.policy.missed = Some(MissedPolicy::RunOnce { within_h: Some(PC_MAINTENANCE_CATCH_UP_H) });
        t.policy.jitter_s = Some(0);
        // retries (a run cut short by a restart of rynas) only within those six hours
        t.policy.window_min = Some(PC_MAINTENANCE_CATCH_UP_H * 60);
        t
    }

    /// The retention of the PC backup folders the NAS owns: two minutes after boot, then
    /// every hour.
    pub fn pc_retention() -> ScheduledTask {
        task(
            PC_RETENTION,
            "PC backup retention",
            "Deletes the old snapshots of the PC backup folders whose retention the NAS owns, and checks that backups arrive. Every hour.",
            TaskAction::PcRetention,
            TaskTrigger::Interval { hours: 1, after_boot_min: 2 },
        )
    }

    /// The task a feature wants, with what a user may change on the Task Scheduler page kept
    /// from the stored one (notifications, priority, timeout, overlap, retry; and whether it
    /// is on, unless the feature decides that: `feature_enables`).
    pub fn keep_options(mut want: ScheduledTask, cur: Option<&ScheduledTask>, feature_enables: bool) -> ScheduledTask {
        if let Some(c) = cur {
            if !feature_enables {
                want.enabled = c.enabled;
            }
            want.notify = c.notify;
            want.notify_output = c.notify_output;
            want.nice = c.nice;
            want.io_weight = c.io_weight;
            want.timeout_s = c.timeout_s;
            want.policy.overlap = c.policy.overlap;
            want.policy.retry = c.policy.retry;
            want.policy.notify = c.policy.notify;
            want.policy.maintenance = c.policy.maintenance;
        }
        want
    }
}
